import {Game,TYPES,PADS} from './engine.js';import {createRenderer} from './render.js';
const $=s=>document.querySelector(s),canvas=$('#game'),draw=createRenderer(canvas);let game=new Game(),selected=-1,inspected=null,paused=false,speed=1,started=false,muted=false,hover=-1,toastTimer=0,frame=0,last=0,terminal=false,audio;
function beep(freq=500,duration=.08,volume=.025){if(muted)return;try{audio??=new AudioContext();if(audio.state==='suspended')audio.resume();let o=audio.createOscillator(),g=audio.createGain();o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(freq*.55,audio.currentTime+duration);g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}catch{}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600);}
function updateUI(){$('#lives').textContent=game.lives;$('#money').textContent=game.money;$('#wave').textContent=`${game.wave} / 15`;$('#next').disabled=game.active||['won','lost'].includes(game.state);$('#next').innerHTML=game.active?'WAVE IN PROGRESS':game.wave===0?'START WAVE <span>➜</span>':'NEXT WAVE <span>➜</span>';$('#waveHint').textContent=game.active?`${game.enemies.length+game.queue.length} uninvited guests left`:game.wave===15?'You did it, stitch by stitch!':`Wave ${game.wave+1}${(game.wave+1)%5===0?' · Boss incoming!':' · Ready when you are'}`;$('#status').textContent=paused?'Take a breather. Your pals will wait.':game.active?'Hold the line, little heroes!':selected>=0?`${TYPES[selected].name}: click a + pad to build.`:game.wave?'A wave well defended. Time to stitch up your strategy.':'A little preparation goes a long way.';document.querySelectorAll('.card').forEach((el,i)=>{el.classList.toggle('selected',selected===i);el.setAttribute('aria-pressed',selected===i);});$('#hint').textContent=selected>=0?TYPES[selected].role+' · click an empty pad':'Pick a pal. Find a perfect spot.';}
function select(i){selected=selected===i?-1:i;inspected=null;$('#inspector').hidden=true;beep(440+i*90,.06);updateUI();}
$('#cards').innerHTML=TYPES.map((t,i)=>`<button class="card" data-type="${i}" aria-pressed="false" title="${t.name}: ${t.role}. Cost ${t.cost} buttons."><span class="key">${i+1}</span><canvas class="portrait" aria-hidden="true"></canvas><strong>${t.short}</strong><small>${t.role}</small><span class="price">✿ ${t.cost}</span></button>`).join('');document.querySelectorAll('.card').forEach(el=>el.onclick=()=>select(+el.dataset.type));
function showInspector(){if(!inspected){$('#inspector').hidden=true;return;}let t=inspected,def=TYPES[t.type];$('#inspector').hidden=false;$('#inspector').innerHTML=`<button class="close" aria-label="Close tower details">×</button><h3>${def.name}</h3><small>LEVEL ${t.level} / 3 · ${def.role}</small><p>Damage ${Math.round(def.damage*Math.pow(1.6,t.level-1))} · Range ${def.range+(t.level-1)*18}<br>${t.type===2?'Chills nearby enemies by 55%.':t.type===0?'Button blasts damage nearby enemies.':'Targets the enemy closest to town.'}</p><button class="action upgrade" ${t.level>=3||game.money<game.upgradeCost(t)?'disabled':''}>${t.level>=3?'FULLY STITCHED ★★★':`UPGRADE · ✿ ${game.upgradeCost(t)}`}</button><button class="action sell">SELL · ✿ ${Math.floor(t.spent*.7)}</button>`;$('#inspector .close').onclick=()=>{inspected=null;showInspector();};$('#inspector .upgrade').onclick=()=>{if(game.upgrade(t)){beep(850,.2);toast('A stronger stitch! Defender upgraded.');showInspector();updateUI();}};$('#inspector .sell').onclick=()=>{game.sell(t);inspected=null;showInspector();updateUI();beep(350,.1);};}
function coords(e){let r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width*1320,y:(e.clientY-r.top)/r.height*620};}
function padAt(p){let best=-1,dist=Infinity;PADS.forEach(([x,y],i)=>{let d=Math.hypot(x-p.x,(y-p.y)*1.3);if(d<55&&d<dist){best=i;dist=d;}});return best;}
canvas.addEventListener('pointermove',e=>{hover=padAt(coords(e));canvas.style.cursor=hover>=0?'pointer':'default';});canvas.addEventListener('pointerleave',()=>hover=-1);canvas.addEventListener('click',e=>{if(!started||paused||['won','lost'].includes(game.state))return;let p=coords(e),i=padAt(p),t=game.towers.find(t=>Math.hypot(t.x-p.x,(t.y-45-p.y)*.8)<48)||game.towers.find(t=>t.pad===i);if(t){selected=-1;inspected=t;showInspector();updateUI();return;}if(i<0){inspected=null;showInspector();return;}if(selected<0){toast('Choose a plush pal below first.');return;}if(game.build(selected,i)){beep(660,.16);toast(`${TYPES[selected].name} reporting for cuddly duty!`);selected=-1;updateUI();}else toast('You need more buttons for that defender.');});
function next(){if(paused){toast('Resume the game to start a wave.');return;}if(game.next()){beep(600,.3);toast(game.wave%5===0?'A Patchwork Brute is on its way!':`Wave ${game.wave}: here come the dust bunnies!`);updateUI();}}
$('#next').onclick=next;$('#speed').onclick=()=>{speed=speed===1?2:speed===2?3:1;$('#speed').textContent=speed+'×';};function togglePause(){if(!started||['won','lost'].includes(game.state)||!$('#overlay').hidden)return;paused=!paused;$('#pause').textContent=paused?'▶':'Ⅱ';$('#pause').setAttribute('aria-label',paused?'Resume game':'Pause game');updateUI();}$('#pause').onclick=togglePause;$('#sound').onclick=()=>{muted=!muted;$('#sound').textContent=muted?'♪̸':'♫';$('#sound').setAttribute('aria-label',muted?'Enable sound':'Mute sound');if(!muted)beep();};
function begin(){started=true;$('#overlay').hidden=true;beep(700,.2);toast('Welcome to Buttonwood! Build a few pals, then start wave 1.');updateUI();}$('#play').onclick=begin;
function dialog(html){$('#overlay').innerHTML=`<div class="dialog">${html}</div>`;$('#overlay').hidden=false;}
$('#help').onclick=()=>{let wasPaused=paused;paused=true;dialog('<div class="big-icon">🧵</div><h2>A stitch in time</h2><p>Choose one of four defenders, then click a <b>+ build pad</b>. Start a wave when your team is ready.<br><br>Click a built tower to upgrade or sell it. Defeated enemies earn buttons. Every fifth wave brings a boss. Keep at least one town heart through all 15 waves to win!</p><button id="closeHelp">GOT IT</button>');$('#closeHelp').onclick=()=>{$('#overlay').hidden=true;paused=wasPaused;};};$('.brand').onclick=e=>{e.preventDefault();$('#help').click();};
document.addEventListener('keydown',e=>{if(!started||!$('#overlay').hidden)return;if(e.code==='Space'){e.preventDefault();togglePause();}if(e.key==='Escape'){selected=-1;inspected=null;showInspector();updateUI();}if(/^[1-4]$/.test(e.key))select(+e.key-1);if(e.key.toLowerCase()==='n')next();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&started&&!paused&&$('#overlay').hidden)togglePause();});
function finish(){terminal=true;let won=game.state==='won';beep(won?950:180,.6);dialog(`<div class="big-icon">${won?'🏆':'🧸'}</div><span class="eyebrow">${won?'BUTTONWOOD IS SAFE':'EVERY HERO STARTS SOMEWHERE'}</span><h2>${won?'A town well stitched!':'Time to patch up.'}</h2><p>${won?'Your little heroes kept the chaos at bay.':'The dust bunnies reached town. Try pairing slowing towers with splash damage.'}<br>${game.wave} waves · ${game.kills} enemies defeated · ${game.lives} hearts</p><button id="restart">PLAY AGAIN ➜</button>`);$('#restart').onclick=()=>{game=new Game();selected=-1;inspected=null;paused=false;speed=1;terminal=false;$('#speed').textContent='1×';$('#pause').textContent='Ⅱ';$('#overlay').hidden=true;showInspector();updateUI();};}
function loop(ts){let dt=Math.min((ts-last)/1000,.05);last=ts;if(started&&!paused&&$('#overlay').hidden){for(let i=0;i<speed;i++)game.update(dt);for(const ev of game.events){if(ev.type==='pop'&&Math.random()<.3)beep(500+Math.random()*300,.045,.012);if(ev.type==='leak'){beep(160,.18);toast('A guest slipped through! Town hearts lost.');}if(ev.type==='clear'){beep(850,.25);toast(`Wave stitched up! +${ev.value} bonus buttons`);}if(ev.type==='shoot'&&Math.random()<.1)beep(ev.tower===2?1100:320,.04,.006);}game.events=[];if(frame%8===0){updateUI();if(inspected&&$('#inspector .upgrade'))$('#inspector .upgrade').disabled=inspected.level>=3||game.money<game.upgradeCost(inspected);}if(!terminal&&['won','lost'].includes(game.state))finish();}draw(game,{hover,selected,inspected,paused,started});frame++;requestAnimationFrame(loop);}
updateUI();requestAnimationFrame(loop);window.stuffy={get game(){return game;},select,next,begin,get paused(){return paused;}};
